import {
  COLOR_TOKENS,
  type ColorName,
  MOTION_TOKENS,
  PHONE_MAX_WIDTH,
  ROUNDED_TOKENS,
  SHADOW_TOKENS,
  SHEET_PEEK_HEIGHT,
  SPACING_TOKENS,
  type ThemeName,
  TYPOGRAPHY_TOKENS,
  type TypographyName,
} from "./tokens.ts";

const HEADER =
  "/* Generated by scripts/generate-theme.ts from src/theme/tokens.ts. Do not edit by hand. */";

const SANS_STACK = '"Overpass", system-ui, -apple-system, "Segoe UI", sans-serif';
const MONO_STACK = '"Overpass Mono", ui-monospace, "SF Mono", Menlo, monospace';

const COLOR_NAMES = Object.keys(COLOR_TOKENS) as ColorName[];

const ROLE_ALIASES: Readonly<Record<string, ColorName>> = {
  selection: "primary",
  "on-selection": "on-primary",
  "selection-text": "primary-text",
  raised: "neutral",
  "ink-muted": "ink-muted",
  surface: "surface",
  ink: "ink",
  hairline: "hairline",
  passed: "passed",
  focus: "focus",
  error: "error",
};

const SHADCN_COMPAT: Readonly<Record<string, string>> = {
  background: "surface",
  foreground: "ink",
  card: "surface",
  "card-foreground": "ink",
  popover: "surface",
  "popover-foreground": "ink",
  primary: "primary",
  "primary-foreground": "on-primary",
  secondary: "neutral",
  "secondary-foreground": "ink",
  muted: "neutral",
  "muted-foreground": "ink-muted",
  accent: "neutral",
  "accent-foreground": "ink",
  destructive: "error",
  border: "hairline",
  input: "hairline",
  ring: "focus",
};

function themeValue(name: ColorName, theme: ThemeName): string {
  const token: { light: string; dark?: string } = COLOR_TOKENS[name];
  return theme === "dark" ? (token.dark ?? token.light) : token.light;
}

const SELECTION_STATES: Readonly<Record<ThemeName, readonly string[]>> = {
  dark: [
    "  --gl-selection-hover: color-mix(in oklab, var(--gl-primary) 92%, var(--gl-ink));",
    "  --gl-selection-active: color-mix(in oklab, var(--gl-primary) 84%, var(--gl-ink));",
  ],
  light: [
    "  --gl-selection-hover: color-mix(in oklab, var(--gl-primary) 84%, var(--gl-primary-text));",
    "  --gl-selection-active: color-mix(in oklab, var(--gl-primary) 68%, var(--gl-primary-text));",
  ],
};

function themeBlock(theme: ThemeName): string {
  const selector =
    theme === "dark" ? ':root,\n:root[data-theme="dark"]' : ':root[data-theme="light"]';
  const lines = COLOR_NAMES.map((name) => `  --gl-${name}: ${themeValue(name, theme)};`);
  return [
    `${selector} {`,
    `  color-scheme: ${theme};`,
    ...lines,
    `  --gl-shadow: ${SHADOW_TOKENS[theme]};`,
    ...SELECTION_STATES[theme],
    "}",
  ].join("\n");
}

function scaleBlock(): string {
  const spacing = Object.entries(SPACING_TOKENS)
    .filter(([name]) => name !== "target-phone")
    .map(([name, value]) => `  --gl-${name}: ${value}px;`);
  const radius = Object.entries(ROUNDED_TOKENS)
    .filter(([name]) => name !== "card-phone")
    .map(([name, value]) => `  --gl-radius-${name}: ${value}px;`);
  return [
    ":root {",
    `  --gl-font-sans: ${SANS_STACK};`,
    `  --gl-font-mono: ${MONO_STACK};`,
    ...spacing,
    ...radius,
    `  --gl-sheet-peek: ${SHEET_PEEK_HEIGHT}px;`,
    `  --gl-duration-panel: ${MOTION_TOKENS.panelMs}ms;`,
    `  --gl-duration-route: ${MOTION_TOKENS.routeDrawMs}ms;`,
    `  --gl-duration-glide: ${MOTION_TOKENS.progressGlideMs}ms;`,
    `  --gl-ease-out: ${MOTION_TOKENS.easeOut};`,
    "}",
    "",
    `@media (max-width: ${PHONE_MAX_WIDTH}px) {`,
    "  :root {",
    `    --gl-target: ${SPACING_TOKENS["target-phone"]}px;`,
    `    --gl-radius-card: ${ROUNDED_TOKENS["card-phone"]}px;`,
    "  }",
    "}",
  ].join("\n");
}

function colorRegistration(): string {
  const roles = Object.entries(ROLE_ALIASES).map(
    ([alias, name]) => `  --color-${alias}: var(--gl-${name});`,
  );
  const direct = COLOR_NAMES.filter(
    (name) => name.startsWith("map-") || name.startsWith("cat-") || name.startsWith("delay-"),
  ).map((name) => `  --color-${name}: var(--gl-${name});`);
  const compat = Object.entries(SHADCN_COMPAT).map(
    ([alias, name]) => `  --color-${alias}: var(--gl-${name});`,
  );
  return [...roles, ...direct, ...compat].join("\n");
}

function themeRegistration(): string {
  return [
    "@theme inline {",
    "  --color-*: initial;",
    "  --font-sans: var(--gl-font-sans);",
    "  --font-mono: var(--gl-font-mono);",
    colorRegistration(),
    "  --color-raised-hover: color-mix(in oklab, var(--gl-neutral) 88%, var(--gl-ink));",
    "  --color-selection-hover: var(--gl-selection-hover);",
    "  --color-selection-active: var(--gl-selection-active);",
    "  --spacing-target: var(--gl-target);",
    "  --radius-sm: 4px;",
    "  --radius-md: var(--gl-radius-thumb);",
    "  --radius-lg: var(--gl-radius-control);",
    "  --radius-xl: var(--gl-radius-card);",
    "  --radius-2xl: 16px;",
    "  --radius-pill: var(--gl-radius-pill);",
    "  --shadow-card: var(--gl-shadow);",
    "  --ease-out: var(--gl-ease-out);",
    "}",
  ].join("\n");
}

function typeUtility(name: TypographyName): string {
  const token = TYPOGRAPHY_TOKENS[name];
  const mono = token.family === "Overpass Mono";
  const spacing: string | undefined = "letterSpacing" in token ? token.letterSpacing : undefined;
  return [
    `@utility type-${name} {`,
    `  font-family: var(--gl-font-${mono ? "mono" : "sans"});`,
    `  font-size: ${token.size}px;`,
    `  font-weight: ${token.weight};`,
    `  line-height: ${token.lineHeight};`,
    ...(spacing ? [`  letter-spacing: ${spacing};`] : []),
    ...(mono
      ? ["  font-variant-numeric: tabular-nums;", '  font-feature-settings: "tnum" 1;']
      : []),
    "}",
  ].join("\n");
}

export function themeCss(): string {
  const typeNames = Object.keys(TYPOGRAPHY_TOKENS) as TypographyName[];
  return `${[
    HEADER,
    themeBlock("dark"),
    themeBlock("light"),
    scaleBlock(),
    themeRegistration(),
    typeNames.map(typeUtility).join("\n\n"),
  ].join("\n\n")}\n`;
}
